package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"time"

	"github.com/labstack/echo/v5"
)

type target struct {
	ID     int    `json:"id"`
	Name   string `json:"name"`
	Email  string `json:"email"`
	Age    int    `json:"age"`
	Active bool   `json:"active"`
}

type rc struct{ r *strings.Reader }

func (n rc) Read(p []byte) (int, error) { return n.r.Read(p) }
func (rc) Close() error                 { return nil }

type nopW struct{ h http.Header }

func (w *nopW) Header() http.Header {
	if w.h == nil {
		w.h = http.Header{}
	}
	return w.h
}
func (*nopW) Write(b []byte) (int, error) { return len(b), nil }
func (*nopW) WriteHeader(int)             {}

func main() {
	const iters = 400000
	body := `{"id":1,"name":"Jon Snow","email":"jon@winterfell.north","age":24,"active":true}`
	e := echo.New()
	var sum, last int
	e.POST("/", func(c *echo.Context) error {
		var t target
		if err := c.Bind(&t); err != nil {
			return err
		}
		sum += t.ID + t.Age + len(t.Name) + len(t.Email)
		last = t.ID
		return nil
	})
	r := strings.NewReader(body)
	req := httptest.NewRequest(http.MethodPost, "/", r)
	req.Header.Set(echo.HeaderContentType, echo.MIMEApplicationJSON)
	req.Body = rc{r}
	w := &nopW{}
	for i := 0; i < 20000; i++ { // warm-up
		r.Reset(body)
		e.ServeHTTP(w, req)
	}
	sum = 0
	start := time.Now()
	for i := 0; i < iters; i++ {
		w.h = nil
		r.Reset(body)
		e.ServeHTTP(w, req)
	}
	d := time.Since(start).Seconds()
	_ = os.MkdirAll("out", 0o755)
	_ = os.WriteFile("out/result.txt", []byte(fmt.Sprintf("sum=%d last=%d\n", sum, last)), 0o644)
	fmt.Printf("PERFPROOF {\"value\": %f}\n", d)
}
EOF
